class Box : NeoObject { }
class Made(NeoVariant<Box> v) {
  public NeoVariant<Box> V = v;
}
class Kid<T> : NeoObject { }
class GenericMade(NeoVariant<Kid<int>> v) { public NeoVariant<Kid<int>> V = v; }
class NullableMade(NeoVariant<Box>? v) { public NeoVariant<Box>? V = v; }
NeoVariant<Box> Named = new(initialize: () => { return new Box(); });
class Seed { public int Amount = 7; }
class Catalog { @id("41ada34f-6c84-47bd-9b80-f2279af04c12") public static List<Seed> Seeds = [@id("614d83e9-40f2-4a4d-9d43-8109f2279a01") new()];
  public static Selection Selection = new(); }
class Selection { public NeoVariant<Box> Bound = Box.Variants.Seeds.BySeed.Bind(Reference(id: "614d83e9-40f2-4a4d-9d43-8109f2279a01")); }
NeoLookupVariantFolder<Box, Seed> Seeds = new(path: "Seeds", collection: Catalog.Seeds, collectionValue: Reference(id: "987bf4b7-3da9-54a0-b4ff-89722c60d177"));
@settings(folder: Seeds)
NeoLookupVariant<Box, Seed> BySeed = new(initialize: (seed) => { return new Box(); });
class LookupMade(NeoLookupVariant<Box, Seed> v) { public NeoLookupVariant<Box, Seed> V = v; }
class Frame : NeoObject { public static int Empty = 0; public Reference<int> Pick = Reference(Frame.Empty); }
class Plant : NeoObject {
  public int Stage = 1;
  public Frame Child = new();
  public bool Refresh() { this.Child.Pick = Reference(this.Stage); var moved = this.ToVariant(Plant.Variants.Grown); return true; }
}
NeoVariant<Plant> Sown = new(initialize: () => { var p = new Plant(); var moved = p.Refresh(); return p; });
NeoVariant<Plant> Grown = new(initialize: () => { return new Plant(); }, apply: (source) => { source.Child.Pick = 5; });
class Probe {
  @storage(allowed: .Save) public static List<Plant> Plants = [];
  public static int WriteThroughReplay() { Probe.Plants.Add(Plant.Variants.Sown.Initialize()); return Probe.Plants[0].Stage * 10 + Probe.Plants[0].Child.Pick; }
  public static LookupMade LookupStored = new(Box.Variants.Seeds.BySeed);
  public static Made BoundStored = new(Box.Variants.Seeds.BySeed.Bind(Reference(id: "614d83e9-40f2-4a4d-9d43-8109f2279a01")));
  public static bool LookupReplay() { return LookupStored.V == Box.Variants.Seeds.BySeed; }
  public static bool BoundReplay() { return BoundStored.V == Catalog.Selection.Bound; }
  public static bool BoundRuntime() { return new Made(Box.Variants.Seeds.BySeed.Bind(Reference<Seed>(id: "614d83e9-40f2-4a4d-9d43-8109f2279a01"))).V == Catalog.Selection.Bound; }
  public static GenericMade GenericStored = new(Kid<int>.Variants.Base);
  public static NullableMade NullStored = new(null);
  public static Made NamedStored = new(Box.Variants.Named);
  public static Made Stored = new(Box.Variants.Base);
  public static bool Runtime() {
    return new Made(Box.Variants.Base).V == Box.Variants.Base;
  }
  public static bool GenericRuntime() { return new GenericMade(Kid<int>.Variants.Base).V == Kid<int>.Variants.Base; }
  public static bool GenericReplay() { return GenericStored.V == Kid<int>.Variants.Base; }
  public static bool NullReplay() { return NullStored.V == null; }
  public static bool NamedReplay() { return NamedStored.V == Box.Variants.Named; }
  public static bool Replay() { return Stored.V == Box.Variants.Base; }
}
